import React from 'react';

const Ahorro = ({ hasSpecificGoal, targetAmount, weeklySavings }) => {
    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <h3>Datos Ahorro</h3>
                <p>¿Tiene Meta Específica?: {hasSpecificGoal ? 'Sí' : 'No'}</p>
                <p>Monto Objetivo: ${targetAmount}</p>
                <p>Ahorros Semanales: ${weeklySavings}</p>
            </div>
        </div>
    );
};

export default Ahorro;
